#!/usr/bin/env python3
"""Generate the next order id."""

import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int) -> str:
    """Convert an integer to a zero-padded 4-character base36 string."""
    digits = []
    for _ in range(4):
        digits.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(digits))


def from_base36(s: str) -> int:
    """Convert a base36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch)
    return n


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-" + to_base36(0))
        return

    if not lines:
        print("ORD-" + to_base36(0))
        return

    last = lines[-1]
    # last line looks like "N\tORD-XXXX" or just "ORD-XXXX"
    suffix = last.split("ORD-")[-1] if "ORD-" in last else last
    num = from_base36(suffix) + 1
    print("ORD-" + to_base36(num))


if __name__ == "__main__":
    main()

