"""Read ids.txt and print the next sequential order id."""

import sys

ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"
BASE = len(ALPHABET)
CHAR_TO_VAL = {c: i for i, c in enumerate(ALPHABET)}


def next_id(current: str) -> str:
    """Increment a 4-character id in the restricted base32 alphabet."""
    chars = list(current)
    for i in range(len(chars) - 1, -1, -1):
        val = CHAR_TO_VAL[chars[i]]
        if val < BASE - 1:
            chars[i] = ALPHABET[val + 1]
            return "".join(chars)
        # Carry over: reset this position to the smallest char
        chars[i] = ALPHABET[0]
    # All positions wrapped — prefix with the smallest char
    return ALPHABET[0] * (len(chars) + 1)


def main():
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-" + ALPHABET[0] * 4)
        return

    if not lines:
        print("ORD-" + ALPHABET[0] * 4)
        return

    last_line = lines[-1]
    # Expect format "ORD-XXXX"
    if not last_line.startswith("ORD-"):
        print(f"error: unexpected id format {last_line!r}", file=sys.stderr)
        sys.exit(1)

    suffix = last_line[4:]
    if len(suffix) != 4 or any(c not in CHAR_TO_VAL for c in suffix):
        print(f"error: invalid suffix {suffix!r} in {last_line!r}", file=sys.stderr)
        sys.exit(1)

    next_suffix = next_id(suffix)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()
