import sys

def to_base36(num: int) -> str:
    """Convert a positive integer to a base-36 string using 0-9 A-Z."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if num == 0:
        return "0"
    result = []
    while num > 0:
        result.append(chars[num % 36])
        num //= 36
    return "".join(reversed(result))

def from_base36(s: str) -> int:
    """Convert a base-36 string to an integer."""
    return int(s, 36)

def main():
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last_line = lines[-1]
    if not last_line.startswith("ORD-") or len(last_line) != 8:
        print("Error: invalid ID format in ids.txt", file=sys.stderr)
        sys.exit(1)

    suffix = last_line[4:]
    num = from_base36(suffix)
    next_num = num + 1
    next_suffix = to_base36(next_num).zfill(4).upper()
    print(f"ORD-{next_suffix}")

if __name__ == "__main__":
    main()

