import re

def to_base36(n, width=4):
    chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    result = ''
    for _ in range(width):
        result = chars[n % 36] + result
        n //= 36
    return result

def main():
    last_id = None
    with open('ids.txt') as f:
        for line in f:
            m = re.search(r'ORD-([0-9A-Z]{4})', line)
            if m:
                last_id = m.group(1)

    if last_id is None:
        raise ValueError('No valid order ID found in ids.txt')

    next_val = int(last_id, 36) + 1
    next_suffix = to_base36(next_val)
    print(f'ORD-{next_suffix}')

if __name__ == '__main__':
    main()

