#!/usr/bin/env python3
"""Read events.jsonl, deduplicate by event_id (first-write-wins), write deduped.jsonl."""

import json
import sys

INPUT = "events.jsonl"
OUTPUT = "deduped.jsonl"


def main():
    seen: set[str] = set()
    kept: list[dict] = []

    try:
        with open(INPUT, "r", encoding="utf-8") as f:
            for lineno, line in enumerate(f, start=1):
                line = line.strip()
                if not line:
                    continue
                try:
                    event = json.loads(line)
                except json.JSONDecodeError as e:
                    print(f"Warning: line {lineno} is not valid JSON, skipping: {e}", file=sys.stderr)
                    continue

                eid = event.get("event_id")
                if eid is None:
                    print(f"Warning: line {lineno} has no 'event_id', keeping it", file=sys.stderr)
                    kept.append(event)
                    continue
                if eid in seen:
                    continue  # duplicate — first occurrence already kept

                seen.add(eid)
                kept.append(event)

        with open(OUTPUT, "w", encoding="utf-8") as f:
            for event in kept:
                f.write(json.dumps(event, ensure_ascii=False) + "\n")

        total_in = sum(1 for _ in open(INPUT, "r", encoding="utf-8") if _.strip())
        print(f"Read {total_in} events, wrote {len(kept)} unique events to {OUTPUT}")

    except FileNotFoundError:
        print(f"Error: {INPUT} not found in current directory", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

