#!/usr/bin/env python3
"""Build manifest.json from files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE = Path("release")
MANIFEST = Path("manifest.json")


def sha256_hex(path: Path) -> str:
    """Return the SHA-256 hex digest of the file at *path*."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            block = f.read(65536)
            if not block:
                break
            h.update(block)
    return h.hexdigest()


def main() -> None:
    if not RELEASE.is_dir():
        print(f"error: {RELEASE} is not a directory")
        raise SystemExit(1)

    manifest = {}
    for path in sorted(RELEASE.rglob("*")):
        if path.is_file():
            # store the path relative to the repo root (e.g. "release/VERSION")
            manifest[str(path)] = sha256_hex(path)

    with open(MANIFEST, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"wrote {MANIFEST} ({len(manifest)} entries)")


if __name__ == "__main__":
    main()

