#!/usr/bin/env python3
"""Count words in all .txt files under docs/ and write sorted counts to counts.txt."""

import os
import re
from collections import Counter

PUNCTUATION = ".,;:!?"
DOCS_DIR = "docs"
OUTPUT_FILE = "counts.txt"


def main() -> None:
    word_counts: Counter = Counter()

    for root, _dirs, files in os.walk(DOCS_DIR):
        for filename in files:
            if not filename.endswith(".txt"):
                continue
            filepath = os.path.join(root, filename)
            with open(filepath, encoding="utf-8") as f:
                for line in f:
                    for raw_word in line.split():
                        word = raw_word.lower().strip(PUNCTUATION)
                        if word:
                            word_counts[word] += 1

    with open(OUTPUT_FILE, "w", encoding="utf-8") as f:
        for word in sorted(word_counts):
            f.write(f"{word} {word_counts[word]}\n")

    print(f"Wrote {len(word_counts)} unique words to {OUTPUT_FILE}")


if __name__ == "__main__":
    main()

