args.content:
"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
from datetime import datetime, timezone

USAGE = "Usage: python rotate.py AS_OF"

def parse_ts(line: str) -> datetime | None:
    """Parse the leading 'YYYY-MM-DD HH:MM:SS' from a log line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(USAGE, file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Invalid timestamp: {sys.argv[1]}", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 86400  # 7 days in seconds

    try:
        with open("app.log") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("app.log not found", file=sys.stderr)
        sys.exit(1)

    keep = []
    archive = []

    for line in lines:
        ts = parse_ts(line)
        if ts is not None and ts.timestamp() < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    with open("archive.log", "a") as f:
        f.writelines(archive)

    with open("app.log", "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

