"""Rotate old entries from app.log to archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Entries in app.log whose
timestamp is strictly older than 7 days before AS_OF are moved to archive.log.
"""

import sys
import time
from datetime import datetime, timezone


def parse_timestamp(line: str) -> datetime | None:
    """Try to parse 'YYYY-MM-DD HH:MM:SS' from the start of a line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, IndexError):
        return None


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("Error: AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 86400  # 7 days in seconds

    # Read all lines from app.log
    try:
        with open("app.log", "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    old_entries: list[str] = []   # to go to archive.log
    new_entries: list[str] = []   # to stay in app.log

    for line in lines:
        dt = parse_timestamp(line)
        if dt is None:
            # Lines without a valid timestamp are kept (not rotated out)
            new_entries.append(line)
        else:
            entry_ts = int(dt.timestamp())
            if entry_ts < cutoff:
                old_entries.append(line)
            else:
                new_entries.append(line)

    # Append old entries to archive.log (preserving order)
    if old_entries:
        with open("archive.log", "a") as f:
            f.writelines(old_entries)

    # Rewrite app.log with the remaining entries
    with open("app.log", "w") as f:
        f.writelines(new_entries)


if __name__ == "__main__":
    main()

